use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    let mut cap: int = 1
    let mut first = true
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut i: int = 0
            let n: int = ks.len() as int
            while i < n {
                if ks[i as usize] == k {
                    ks.remove(i as usize)
                    vs.remove(i as usize)
                    break
                }
                i = i + 1
            }
            ks.insert(0, k)
            vs.insert(0, v)
            if ks.len() as int > cap {
                let last = ks.len() - 1
                println("evict ${ks[last]}")
                ks.remove(last)
                vs.remove(last)
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found: int = -1
            let mut i: int = 0
            let n: int = ks.len() as int
            while i < n {
                if ks[i as usize] == k {
                    found = vs[i as usize]
                    ks.remove(i as usize)
                    vs.remove(i as usize)
                    ks.insert(0, k)
                    vs.insert(0, found)
                    break
                }
                i = i + 1
            }
            println("${found}")
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i: int = 0
                let n: int = ks.len() as int
                while i < n {
                    if i > 0 {
                        out = out + " "
                    }
                    out = out + "${ks[i as usize]}"
                    i = i + 1
                }
                println(out)
            }
        }
    }
}

